$pageTitle='';$pageTemplate='';
if($signedIn) {
    if($screen==='workout_editor'){$pageTitle='Edit Workout';$pageTemplate='/workout-editor.php';}
    elseif(in_array($screen,array('swimmer','locations','garmin_setup'),true)) { $pageTitle='Settings';$pageTemplate='/settings.php'; }
    elseif(in_array($screen,array('garmin_activities','garmin_measurements','garmin_history'),true)) { $pageTitle='Garmin';$pageTemplate='/garmin.php'; }
